    {"id": 3, "claim": "Option (C) suggests the Qin Dynasty, which is a political unification event, not the origin of civilization itself.", "evidence": "The Qin Dynasty began in 221 BCE, long after the establishment of Chinese civilization and culture.", "weight": 0.7, "depends_on": [1]},
    {"id": 4, "claim": "Option (D) suggests external influences from the Indus Valley as the primary origin, which is not supported by mainstream historical consensus regarding the independent development of Chinese culture.", "evidence": "While there were some ancient connections, Chinese civilization is widely regarded as having indigenous roots in the Neolithic period.", "weight": 0.6, "depends_on": [1]},
